  // `animate` est lu une fois, à la création : revenir d'une collection remontre le titre sans le réécrire.
  let { size = 64, animate = true, onplayed }: { size?: number; animate?: boolean; onplayed?: () => void } = $props();
  const play = untrack(() => animate);
  onMount(() => onplayed?.());
</script>

